action.code:
// Initialize start node
start_node_->g_value = 0.0;
start_node_->h_value = calc_h_value(start_node_);
start_node_->parent = nullptr;

// Add start node to open list
open_list_.push_back(start_node_);

// Main A* search loop
while (!open_list_.empty()) {
    // Get node with lowest f_value (g + h)
    RouteModel::Node* current_node = next_node();

    // Check if we reached the end node
    if (current_node == end_node_) {
        distance_ = end_node_->g_value;
        break;
    }

    // Add neighbors to open list
    add_neighbors(current_node);

    // Mark current node as visited
    current_node->visited = true;

    // Remove current node from open list
    open_list_.erase(std::remove(open_list_.begin(), open_list_.end(), current_node), open_list_.end());
}

// Construct the final path from end node to start node
m_model_.path = construct_final_path(end_node_);

